from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django_otp.plugins.otp_totp.models import TOTPDevice

class TOTPDeviceDeactivateView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def delete(self, request, device_id):
        # Ensure the device belongs to the authenticated user before deletion
        device = TOTPDevice.objects.filter(id=device_id, user=request.user).first()
        if not device:
            return Response({"error": "Device not found"}, status=status.HTTP_404_NOT_FOUND)

        device.delete()
        return Response({"status": "MFA device unlinked"}, status=status.HTTP_200_OK)
